/**
 * Whether a catalogue entry can actually be installed with one click.
 *
 * WHY THIS IS ITS OWN MODULE. Two independent things have to both be true, and
 * until now neither was checked before the button was drawn:
 *
 *   1. the worker knows WHERE this game keeps its mods
 *      (worker/game-mods.ts's `modDirShell`), and
 *   2. the worker can turn this entry's source into a DOWNLOAD URL
 *      (worker/game-mods.ts's `resolveUrl`).
 *
 * The catalogue is far wider than either. Expanding it from 124 entries across
 * five games to 491 across eight made that gap much bigger rather than smaller:
 * every Factorio, Satisfactory, Palworld, CS2 and V Rising entry got an Install
 * button that reaches the worker and comes back "Auto-install isn't wired for
 * this game yet." A button whose only outcome is an error is worse than no
 * button, and it is worse again at 178 of them.
 *
 * So the two lists live here, `worker/game-mods.ts` imports them rather than
 * keeping its own copies, and the panel asks the same question before it
 * decides what to render. One source of truth, so the UI and the worker cannot
 * disagree about what is possible.
 *
 * ADDING A FAMILY is deliberately a two-part job: add its directory to
 * `modDirShell` AND its slug here. Adding it here alone re-creates exactly the
 * failure this module exists to prevent.
 */

/** Families whose mod directory `worker/game-mods.ts` knows how to find. */
export const INSTALLABLE_FAMILIES = new Set([
  "minecraft",
  "rust",
  "valheim",
  // ── Steam Workshop, NxLabs Phase 3 (2026-09-20) ── pure config-write: the
  // worker writes the Workshop ID into whichever env var / config file /
  // launch arg this specific family's dedicated server already reads on
  // boot, and the GAME ITSELF fetches the content from Steam — Nxeon never
  // downloads or mirrors the file. Two families are deliberately NOT here
  // despite being in Phase 3's target list: `icarus` has no real Steam
  // Workshop integration at all (confirmed against its official dedicated
  // server docs — nothing to install), and `palworld`'s official Workshop
  // support is Windows-dedicated-server-only while Nxeon's Palworld image is
  // Linux, so there is no real activation path on the servers Nxeon actually
  // runs. See worker/game-mods.ts's Steam Workshop section for the per-family
  // mechanism and docs/DOCUMENTATION.md's 2026-09-20 entry for the research
  // and confidence level behind each one.
  "ark",
  "unturned",
  "dst",
  "squad",
  "soulmask",
  "projectzomboid",
  "tf2",
  "l4d2",
  "empyrion",
  // ── Terraria / TShock plugins (2026-09-30) ── real .dll plugins from their
  // authors' own GitHub releases, placed into a host folder TShock is told to
  // load from, then PROVEN loaded by restarting and reading TShock's own
  // "Plugin X vY initiated." line (rolled back if it isn't) — see the
  // Terraria section of worker/game-mods.ts for the mechanism and why it
  // deliberately does NOT mount over /tshock/ServerPlugins.
  //
  // Two things this entry depends on that weren't true before 2026-09-30,
  // both verified against a real provisioned `ryshe/terraria` container
  // (TShock 6.1.0.0) rather than assumed:
  //   - somewhere to put a plugin: prisma/catalog.ts's terraria setupScript
  //     now bind-mounts /opt/terraria-plugins and passes TSAPI's own
  //     `-additionalplugins` flag. A server provisioned BEFORE that has
  //     neither, and the worker detects that from the live container and
  //     says so (TERRARIA_NOT_ENABLED) instead of placing a file TShock
  //     would never read.
  //   - a catalogue that is actually for this product: the 1000 previously
  //     seeded Terraria rows were tModLoader Steam Workshop items (a
  //     different Terraria variant Nxeon never installs — permanently inert
  //     here) and are replaced by scripts/seed-terraria-tshock-plugins.ts's
  //     short list of real TShock plugins, each one test-loaded on that real
  //     container before it was listed.
  "terraria",
]);

/** Sources `worker/game-mods.ts` can resolve to a downloadable file. */
export const RESOLVABLE_SOURCES = new Set([
  "modrinth",
  "spigotmc",
  "umod",
  "thunderstore",
  "github",
  // Not a "downloadable file" in the same sense as the others — see the big
  // comment above INSTALLABLE_FAMILIES's Workshop entries — but it has to be
  // in this set too: `installSupport()` below requires BOTH the family and
  // the source to be listed before it will draw an Install button at all.
  "steam_workshop",
]);
// "github" added 2026-09-20 alongside scripts/import-github-catalog.ts (real CS2
// plugin catalogue). Resolving works today (worker/game-mods.ts's resolveUrl
// hits the repo's real `/releases/latest` asset). As of 2026-09-30 terraria is
// the first github-sourced family in INSTALLABLE_FAMILIES (TShock plugins,
// single-.dll assets only — see resolveUrl's terraria branch); cs2 mods still show
// installSupport's "family" reason (INSTALLABLE_FAMILIES has no cs2 entry:
// nobody has written the real SSH mod-directory convention for a CS2 dedicated
// server yet, see modDirShell's TODO in worker/game-mods.ts). Wiring
// RESOLVABLE_SOURCES ahead of INSTALLABLE_FAMILIES is deliberate: it makes the
// panel's error message correctly blame the game ("not wired for this game
// yet") instead of the source, and it means the day someone adds a `cs2` case
// to modDirShell, install just works with no further changes here.

/**
 * PER-FAMILY SOURCE ALLOWLIST (2026-09-30 family-coverage pass).
 *
 * The two sets above answer "is this family wired?" and "is this source
 * fetchable?" independently — which stopped being enough once families
 * started carrying rows from more than one source, only one of which the
 * worker actually knows how to install for THAT family. Space Engineers has
 * both Steam Workshop and mod.io rows; Palworld has Workshop and Nexus rows;
 * Minecraft has two GitHub rows that the generic github adapter "installed"
 * by unzipping a release jar into a plugins/ SUBFOLDER Paper never scans — a
 * reported success with nothing loaded. The pair check alone would draw a
 * button for every one of those. terraria is the same shape: its catalogue
 * held 1000 `steam_workshop` rows until 2026-09-30 (tModLoader items Nxeon's
 * TShock servers can never load), so it's restricted to `github` (real TShock
 * plugin .dll releases) — see scripts/seed-terraria-tshock-plugins.ts.
 *
 * A family listed here only offers one-click install for the sources named;
 * any other source on that family gets the honest manual-install message. A
 * family NOT listed keeps the old family-and-source behaviour. Every family
 * added to INSTALLABLE_FAMILIES by this pass is added through this map,
 * below, so the two can't drift.
 */
export const FAMILY_SOURCES: Readonly<Record<string, readonly string[]>> = {
  // ── pre-existing families, recorded explicitly (what the worker really does) ──
  // 2026-10-01 (K1 one-click installers): minecraft/valheim/rust/cs2/factorio now
  // install through lib/mods/engine.ts + lib/mods/installers/<family>.ts —
  // verified downloads, dependency resolution, safe archive placement,
  // enable/disable/update. test/mods-installers.test.ts asserts every engine
  // installer's sources are listed here, so the two can't drift.
  minecraft: ["modrinth", "spigotmc", "hangar"],
  rust: ["umod"],
  valheim: ["thunderstore"],
  ark: ["steam_workshop"],
  unturned: ["steam_workshop"],
  dst: ["steam_workshop"],
  squad: ["steam_workshop"],
  soulmask: ["steam_workshop"],
  projectzomboid: ["steam_workshop"],
  tf2: ["steam_workshop"],
  l4d2: ["steam_workshop"],
  empyrion: ["steam_workshop"],
  // ── TShock plugins (2026-09-30) — see INSTALLABLE_FAMILIES's terraria entry ──
  terraria: ["github"],
  // ── added 2026-09-30 — see worker/game-mods.ts's family-coverage section ──
  vintagestory: ["vintagestory_moddb"], // official ModDB, placed in data/Mods (+ modinfo.json dependencies)
  gmod: ["steam_workshop"], // .gma into garrysmod/addons + resource.AddWorkshop for clients
  necesse: ["steam_workshop"], // mod .jar into the data dir's mods/
  kf2: ["steam_workshop"], // image env → ServerSubscribedWorkshopItems; the server downloads itself
  armareforger: ["reforger_workshop"], // image env → game.mods; the server downloads from Bohemia itself
  satisfactory: ["ficsit"], // ficsit.app LinuxServer builds (+ SML and other dependencies)
  // ── engine families added 2026-10-01 ──
  cs2: ["github"], // CounterStrikeSharp plugins (needs Metamod + CSS already on the server)
  factorio: ["factorio_portal"], // official portal zips (needs the owner's factorio.com token in server-settings.json)
};
for (const [family, sources] of Object.entries(FAMILY_SOURCES)) {
  INSTALLABLE_FAMILIES.add(family);
  for (const s of sources) RESOLVABLE_SOURCES.add(s);
}

export type InstallSupport =
  | { ok: true }
  | { ok: false; reason: "family" | "source"; message: string };

/**
 * Can this entry be installed for the customer, or does it have to be done by
 * hand? The message is customer-facing and says which of the two is missing,
 * because they lead to different next steps: a family we can't reach means
 * upload it yourself, a source we can't fetch from means download it first.
 */
export function installSupport(family: string, source: string): InstallSupport {
  if (!INSTALLABLE_FAMILIES.has(family)) {
    return {
      ok: false,
      reason: "family",
      message: "We can't place files for this game automatically yet — install it yourself in Files.",
    };
  }
  const allowed = FAMILY_SOURCES[family];
  if (!RESOLVABLE_SOURCES.has(source) || (allowed && !allowed.includes(source))) {
    return {
      ok: false,
      reason: "source",
      message:
        family === "terraria"
          ? "This isn't a TShock plugin — Nxeon's Terraria servers run TShock, which can't load tModLoader or Steam Workshop mods."
          : "This source doesn't offer a direct download we can fetch — grab the file and upload it in Files.",
    };
  }
  return { ok: true };
}
/**
 * Per-family one-click mod coverage — the single table the worker, the portal
 * and docs/MODS-COVERAGE.md agree on.
 *
 *  engine      — lib/mods/engine.ts + an installer in this folder (resolve →
 *                verified download → safe placement → state/rollback). Supports
 *                install, update, enable/disable, uninstall.
 *  legacy      — a family-specific path in worker/game-mods.ts that predates
 *                the engine and was verified on a live server (Steam Workshop
 *                config-writes, TShock restart-and-verify, Vintage Story,
 *                Satisfactory, Arma Reforger). Install + uninstall; the
 *                game itself owns updates for Workshop families.
 *  unavailable — no honest one-click path yet; `reason` says why, in words a
 *                customer can act on. The panel shows the catalogue with
 *                manual-install guidance, never an Install button.
 */
import type { FamilyInstaller } from "../types";
import { minecraftInstaller } from "./minecraft";
import { valheimInstaller } from "./valheim";
import { rustInstaller } from "./rust";
import { cs2Installer } from "./cs2";
import { factorioInstaller } from "./factorio";

export const ENGINE_INSTALLERS: Record<string, FamilyInstaller> = {
  minecraft: minecraftInstaller,
  valheim: valheimInstaller,
  rust: rustInstaller,
  cs2: cs2Installer,
  factorio: factorioInstaller,
};

export function engineInstallerFor(family: string, source: string): FamilyInstaller | null {
  const i = ENGINE_INSTALLERS[family];
  return i && i.sources.includes(source) ? i : null;
}

export type Coverage =
  | { mode: "engine"; sources: readonly string[]; mechanism: string }
  | { mode: "legacy"; sources: readonly string[]; mechanism: string }
  | { mode: "unavailable"; reason: string };

/** Families with a pre-engine worker path (see worker/game-mods.ts). */
const LEGACY: Record<string, { sources: string[]; mechanism: string }> = {
  terraria: { sources: ["github"], mechanism: "TShock plugin .dll → restart → confirmed from TShock's own load log, rolled back otherwise." },
  ark: { sources: ["steam_workshop"], mechanism: "Workshop ids → GAME_MOD_IDS on the container; the server downloads them itself." },
  unturned: { sources: ["steam_workshop"], mechanism: "Workshop ids → WorkshopDownloadConfig.json; the server downloads them itself." },
  dst: { sources: ["steam_workshop"], mechanism: "Workshop ids → MODS env (dedicated_server_mods_setup.lua); the server downloads them." },
  squad: { sources: ["steam_workshop"], mechanism: "Workshop ids → MODS env; the image fetches them." },
  soulmask: { sources: ["steam_workshop"], mechanism: "Workshop ids → MOD_IDS env." },
  projectzomboid: { sources: ["steam_workshop"], mechanism: "WorkshopItems= + Mods= in servertest.ini (mod ids read from mod.info)." },
  tf2: { sources: ["steam_workshop"], mechanism: "tf_workshop_map_sync lines in server.cfg (needs a Workshop auth key)." },
  l4d2: { sources: ["steam_workshop"], mechanism: "steamcmd fetch in the container → addons/*.vpk + addonlist.txt." },
  empyrion: { sources: ["steam_workshop"], mechanism: "One Workshop scenario → Content/Scenarios + dedicated.yaml CustomScenario." },
  kf2: { sources: ["steam_workshop"], mechanism: "ServerSubscribedWorkshopItems in LinuxServer-KFEngine.ini." },
  gmod: { sources: ["steam_workshop"], mechanism: "steamcmd fetch → gmad extract into addons/ + resource.AddWorkshop." },
  necesse: { sources: ["steam_workshop"], mechanism: "steamcmd fetch → mod .jar into mods/." },
  vintagestory: { sources: ["vintagestory_moddb"], mechanism: "ModDB release for the server's version → data/Mods, dependencies from modinfo.json, load confirmed from the log." },
  armareforger: { sources: ["reforger_workshop"], mechanism: "MODS_JSON_B64 → game.mods; the server downloads from Bohemia's workshop." },
  satisfactory: { sources: ["ficsit"], mechanism: "ficsit.app LinuxServer builds (+ SML) into FactoryGame/Mods/<ref>." },
