/** Why each remaining family has no one-click install (customer-facing). */
const UNAVAILABLE: Record<string, string> = {
  palworld: "Palworld's Workshop mods only load on Windows dedicated servers, and pak/UE4SS mods on Linux aren't something we can verify loading yet. Upload pak mods to Pal/Content/Paks/~mods in Files.",
  sdtd: "7 Days to Die mods are distributed outside any API we can install from (mostly Nexus). Upload them to serverfiles/Mods in Files.",
  vrising: "V Rising server mods (BepInEx) aren't wired yet — the server image doesn't ship BepInEx.",
  enshrouded: "Enshrouded has no server-side mod system yet.",
  conan: "Conan Exiles' Workshop mods need the Windows server's mod list, which the Linux image we run hasn't been verified with yet.",
  arma3: "Arma 3 Workshop downloads need a logged-in Steam account that owns the game — not wired yet.",
