export function familyCoverage(family: string): Coverage {
  const e = ENGINE_INSTALLERS[family];
  if (e) return { mode: "engine", sources: e.sources, mechanism: e.mechanism };
  const l = LEGACY[family];
  if (l) return { mode: "legacy", sources: l.sources, mechanism: l.mechanism };
  return { mode: "unavailable", reason: UNAVAILABLE[family] ?? "One-click mods aren't available for this game yet. Upload files in Files and restart from Console." };
}

export const COVERAGE_LEGACY = LEGACY;
export const COVERAGE_UNAVAILABLE = UNAVAILABLE;

export type BrowseCard = {
  id: string;
  slug: string;
  name: string;
  author: string | null;
  summary: string | null;
  icon: string | null;
  /** Upstream icon, used when our mirrored copy fails to load. */
  iconFallback: string | null;
  category: string;
  source: string;
  downloads: number | null;
  updatedAt: string | null;
  fileBytes: number | null;
  featured: boolean;
  paid: boolean;
  impact: string;
  compat: Compat | null;
  manualInstall: string | null;
  status: string | null;
  version: string | null;
  error: string | null;
  verified: BadgeView | null;
  clientRequired: boolean | null;
  dependencyCount: number;
  latestVersion: string | null;
};

type State = { status: string; version: string | null; error: string | null };

function toCard(m: GameMod, ctx: BrowseServer | null, st: State | undefined, badge: LiveBadge | undefined): BrowseCard {
  const fam = m.gameFamily;
  const cov = familyCoverage(fam);
  const sup = installSupport(fam, m.source);
  const compat = ctx ? compatFor(fam, m, ctx.facts) : null;
  return {
    id: m.id,
    slug: m.slug,
    name: m.name,
    author: m.authorName,
    summary: m.description,
    icon: modIconSrc(m),
    iconFallback: m.iconKey ? httpsUrl(m.iconUrl) : null,
    category: m.category,
    source: m.source,
    downloads: m.downloads,
    updatedAt: (m.upstreamUpdatedAt ?? null)?.toISOString() ?? null,
    fileBytes: m.fileBytes,
    featured: m.featured,
    paid: m.paid,
    impact: m.impact,
    compat,
    manualInstall: cov.mode === "unavailable" ? cov.reason : !sup.ok ? sup.message : compat?.verdict === "unsupported" ? compat.detail : null,
    status: st?.status ?? null,
    version: st?.version ?? null,
    error: st?.error ?? null,
    verified: badgeView(fam, badge),
    clientRequired: clientRequired(m),
    dependencyCount: m.dependencyCount,
    latestVersion: m.latestVersion,
  };
}

/** true = players must install it too; false = server-only; null = the source doesn't say. */
export function clientRequired(m: object): boolean | null {
  const cs = optStr(m, "clientSide", "client_side");
  if (cs === "required") return true;
  if (cs === "unsupported" || cs === "optional") return false;
  const flag = opt<boolean>(m, "clientRequired");
  if (typeof flag === "boolean") return flag;
  // Thunderstore (Valheim) rows carry no flag: ask the shared classifier (prd-032),
  // but only believe it when it had evidence (curated list / provider tag / a per-game rule).
  const fam = optStr(m, "gameFamily");
  if (fam) {
    const v = clientWarningFor(
      { gameFamily: fam, source: optStr(m, "source") ?? "", sourceId: optStr(m, "sourceId"), name: optStr(m, "name") ?? "", categories: opt<string[]>(m, "categories") ?? [], clientSide: cs ?? null, serverSide: optStr(m, "serverSide") },
      null,
    );
    if (v.basis !== "unknown") return v.required;
  }
  return null;
}

export type BrowsePage = { items: BrowseCard[]; total: number; page: number; pageSize: number; hasMore: boolean; appliedVersion: string | null };

export async function browseMods(family: string, query: BrowseQuery, ctx: BrowseServer | null): Promise<BrowsePage> {
  const q = normQuery(query);
  const version = q.gameVersion ?? ctx?.facts.pinnedVersion ?? null;
  const verifiedIds = q.verifiedOnly ? await liveVerifiedModIds(family, { gameVersion: VERSIONED_FAMILIES.has(family) ? version : null, loaders: ctx?.accepted.length ? ctx.accepted : undefined }) : null;
  const where = buildBrowseWhere(family, q, ctx ? { variant: ctx.facts.variant, pinnedVersion: ctx.facts.pinnedVersion } : null, verifiedIds);
  const skip = (q.page - 1) * BROWSE_PAGE_SIZE;
  const [total, rows, states] = await Promise.all([
    cachedCount(where),
    db.gameMod.findMany({ where, orderBy: ORDER[q.sort], skip, take: BROWSE_PAGE_SIZE }),
    ctx ? db.serverMod.findMany({ where: { serverId: ctx.serverId }, select: { modId: true, status: true, version: true, error: true } }) : Promise.resolve([]),
  ]);
  const badges = await liveBadges(rows.map((r) => r.id), { gameVersion: VERSIONED_FAMILIES.has(family) ? version : null, loaders: ctx?.accepted.length ? ctx.accepted : undefined });
  const st = new Map(states.map((s) => [s.modId, s]));
  return {
    items: rows.map((m) => toCard(m, ctx, st.get(m.id), badges.get(m.id))),
    total,
    page: q.page,
    pageSize: BROWSE_PAGE_SIZE,
    hasMore: skip + rows.length < total,
    appliedVersion: VERSIONED_FAMILIES.has(family) ? (q.gameVersion ?? (q.compatibleOnly ? ctx?.facts.pinnedVersion ?? null : null)) : null,
  };
}

// ── preview ──────────────────────────────────────────────────────────────────
export type DepView = {
  kind: "required" | "optional" | "incompatible" | "embedded";
  name: string;
  /** Catalogue entry for one-click install, when we have one. */
  modId: string | null;
  slug: string | null;
  icon: string | null;
  url: string | null;
  status: string | null;
};

export type VersionView = {
  id: string;
  number: string;
