import { Icon } from "@/components/nx/Icon";
import type { BrowseCard } from "@/lib/mods-browse";
import { Chip, CompatChip, ModIcon, PENDING, SOURCE_LABEL, STATE, ago, compactNum, fileSize } from "./bits";
import { VerifiedBadge } from "./VerifiedBadge";

/**
 * One catalogue card. The whole card opens the preview (a real <button> for
 * the title so keyboard users get it); Install is its own button and does not
 * open the preview. Every number is the source's own, or absent.
 */
export function ModCard({ m, unavailable, busy, onOpen, onInstall }: { m: BrowseCard; unavailable: boolean; busy: boolean; onOpen: () => void; onInstall: () => void }) {
  const st = m.status ? STATE[m.status] : null;
  const installed = m.status === "INSTALLED" || m.status === "DISABLED" || (!!m.status && PENDING.has(m.status));
  const dl = compactNum(m.downloads);
  const up = ago(m.updatedAt);
  const size = fileSize(m.fileBytes);
  return (
    <article
      onClick={onOpen}
      className="group relative flex cursor-pointer flex-col gap-2.5 rounded-[15px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.66))] p-3.5 transition hover:-translate-y-[1px] hover:border-brand-400/45 hover:shadow-[0_10px_30px_-18px_rgba(123,63,239,.7)]"
    >
      <div className="flex items-start gap-3">
        <ModIcon src={m.icon} fallback={m.iconFallback} />
        <div className="flex min-w-0 flex-1 flex-col">
          <h3 className="min-w-0">
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); onOpen(); }}
              className="block max-w-full truncate text-left text-[14px] font-bold text-white outline-none after:absolute after:inset-0 after:rounded-[15px] focus-visible:after:outline focus-visible:after:outline-2 focus-visible:after:outline-brand-400"
            >
              {m.name}
            </button>
          </h3>
          <p className="mt-0.5 truncate text-[11.5px] text-tx-faint">
            {m.author ? <>by <span className="text-tx-dim">{m.author}</span> · </> : null}
            {m.category} · {SOURCE_LABEL[m.source] ?? m.source}
          </p>
        </div>
      </div>

      <div className="relative z-[1] flex flex-wrap items-center gap-1.5">
        {m.verified && <VerifiedBadge badge={m.verified} stopPropagation />}
        {!unavailable && <CompatChip compat={m.compat} />}
        {st && <Chip cls={st.cls}>{st.label}{m.status === "INSTALLED" && m.version ? ` · ${m.version}` : ""}</Chip>}
        {m.featured && <Chip cls="border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]">Featured</Chip>}
        {m.clientRequired && <Chip cls="border-amber-500/40 bg-amber-500/10 text-amber-200" icon="users" title="Players need this mod installed in their own game too">Players need it too</Chip>}
        {m.impact === "heavy" && <Chip cls="border-amber-500/45 bg-amber-500/12 text-amber-300">Heavy</Chip>}
      </div>

      {m.summary && <p className="line-clamp-2 text-[12.5px] leading-relaxed text-tx-dim">{m.summary}</p>}

      <div className="mt-auto flex flex-wrap items-center gap-x-3 gap-y-1 text-[11.5px] text-tx-faint">
        {dl && <span className="num inline-flex items-center gap-1"><Icon name="download" size={11} tone="inherit" />{dl}</span>}
        {up && <span className="inline-flex items-center gap-1"><Icon name="clock" size={11} tone="inherit" />{up}</span>}
        {size && <span className="num">{size}</span>}
        {m.dependencyCount > 0 && <span>+{m.dependencyCount} dep{m.dependencyCount === 1 ? "" : "s"}</span>}
      </div>

      {m.status === "FAILED" && m.error && <p className="relative z-[1] rounded-[9px] border border-red-500/30 bg-red-500/[0.07] px-2.5 py-1.5 text-[11.5px] leading-snug text-red-300">{m.error}</p>}

      <div className="relative z-[1] flex items-center gap-2 border-t border-white/[0.06] pt-2.5">
        {installed ? (
          <span className="text-[11.5px] text-tx-faint">{m.status === "INSTALLED" ? "On your server" : st?.label ?? ""}</span>
        ) : m.manualInstall ? (
          <span className="line-clamp-1 min-w-0 flex-1 text-[11.5px] leading-snug text-tx-faint" title={m.manualInstall}>{m.manualInstall}</span>
        ) : (
          <button
            type="button"
            disabled={busy}
            onClick={(e) => { e.stopPropagation(); onInstall(); }}
            className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50"
            aria-label={`Install ${m.name}`}
          >
            {m.status === "FAILED" ? "Try again" : "Install"}
          </button>
        )}
        <span className="ml-auto inline-flex items-center gap-1 text-[11.5px] font-semibold text-tx-faint transition group-hover:text-white">
          Details <span aria-hidden className="transition group-hover:translate-x-0.5">→</span>
        </span>
      </div>
    </article>
  );
}

