/**
 * mod.io (REST v1) — Core Keeper, Space Engineers, Squad's Sandstorm, Mordhau, Eco. Needs MODIO_API_KEY
 * (skipped with an admin message when absent). Read-only API key (`api_key` query param — redacted
 * from every logged error by lib/modsync/http.ts).
 *
 * Policy: METADATA + LINK-THROUGH ONLY. mod.io downloads are governed by each game's mod.io agreement
 * and per-user terms; we never download or mirror. `fileUrl` is not stored (mod.io binary URLs are
 * short-lived and key-bound). Licence: none exposed => null.
 * Rate: 50 req/min (documented 60/min for API-key reads).
 */
import type { NormalizedMod, Provider, SliceResult, SyncContext } from "../types";

const API = "https://api.mod.io/v1";
const PAGE = 100;

export const MODIO_GAMES: { id: number; family: string; tagFilter?: string; categoryGroup?: string }[] = [
  { id: 5289, family: "corekeeper", categoryGroup: "Type" },
  { id: 264, family: "spaceengineers", tagFilter: "Mod" },
  { id: 254, family: "sandstorm", categoryGroup: "Mods" },
  { id: 169, family: "mordhau", categoryGroup: "Type" },
  { id: 6, family: "eco", categoryGroup: "Type" },
];

export interface MioImage { filename?: string; original: string; thumb_320x180?: string }
export interface MioMod {
  id: number; name: string; name_id: string; summary?: string; description?: string; description_plaintext?: string; profile_url: string;
  homepage_url?: string | null; date_added?: number; date_updated?: number; date_live?: number;
  logo?: MioImage | null; media?: { images?: MioImage[]; youtube?: string[] };
  tags?: { name: string }[]; submitted_by?: { username?: string; display_name_portal?: string | null; avatar?: { original?: string } | null; profile_url?: string };
  stats?: { downloads_total?: number; subscribers_total?: number; ratings_total?: number; ratings_percentage_positive?: number };
  modfile?: { id: number; filesize?: number; filehash?: { md5?: string }; filename?: string; version?: string | null; changelog?: string | null; date_added?: number } | null;
  community_options?: number;
}

const unesc = (s: string | undefined) => (s ?? "").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#039;|&#39;/g, "'");
const dt = (n?: number) => (n ? new Date(n * 1000) : null);

export function parseModioMod(m: MioMod, family: string, groupValues?: Set<string>): NormalizedMod {
  const tags = (m.tags ?? []).map((t) => t.name);
  const cat = groupValues ? tags.find((t) => groupValues.has(t)) : undefined;
  const mf = m.modfile;
  const total = m.stats?.ratings_total ?? 0;
  const user = m.submitted_by;
  const side = tags.includes("Server") ? "required" : tags.includes("Client") ? "unsupported" : null;
  return {
    gameFamily: family,
    source: "mod_io",
    sourceId: String(m.id),
    slugHint: m.name_id,
    name: unesc(m.name),
    category: cat ?? "Mods",
    description: unesc(m.summary) || null,
    body: m.description || null,
    bodyFormat: "html",
    url: m.profile_url,
    websiteUrl: m.homepage_url || null,
    iconUrl: m.logo?.thumb_320x180 ?? m.logo?.original ?? null,
    media: [
      ...(m.logo?.original ? [{ kind: "banner" as const, url: m.logo.original }] : []),
      ...(m.media?.images ?? []).map((i) => ({ kind: "screenshot" as const, url: i.original })),
      ...(m.media?.youtube ?? []).map((y) => ({ kind: "video" as const, url: `https://www.youtube.com/watch?v=${y}` })),
    ],
    authorName: user?.display_name_portal || user?.username || null,
    authorAvatarUrl: user?.avatar?.original ?? null,
    authors: user?.username ? [{ name: user.display_name_portal || user.username, url: user.profile_url ?? null, avatarUrl: user.avatar?.original ?? null }] : undefined,
    license: null,
    downloads: m.stats?.downloads_total ?? null,
    followers: m.stats?.subscribers_total ?? null,
    rating: total >= 5 && m.stats?.ratings_percentage_positive != null ? Math.round(m.stats.ratings_percentage_positive / 2) / 10 : null,
    ratingCount: total || null,
    categories: cat ? [cat] : [],
    tags,
    serverSide: side,
    firstPublishedAt: dt(m.date_live ?? m.date_added),
    upstreamUpdatedAt: dt(m.date_updated),
    versions: mf
      ? [{
          versionId: String(mf.id),
          versionNumber: (mf.version || mf.filename || String(mf.id)).slice(0, 120),
          channel: "release",
          gameVersions: [],
          loaders: [],
          fileName: mf.filename ?? null,
          fileBytes: mf.filesize ?? null,
          changelog: mf.changelog || null,
          publishedAt: dt(mf.date_added),
          serverSideReq: side,
        }]
      : [],
  };
}

export const modio: Provider = {
  key: "mod_io",
  label: "mod.io",
  games: MODIO_GAMES.map((g) => g.family),
  ratePerMin: 50,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  requiresEnv: ["MODIO_API_KEY"],
  keyHelp: "Set MODIO_API_KEY (mod.io/me/access) in /opt/nxeon/.env and restart the worker.",
  async run(ctx: SyncContext): Promise<SliceResult> {
    const key = process.env.MODIO_API_KEY!;
    let gi = Number(ctx.cursor?.gi ?? 0);
    let offset = Number(ctx.cursor?.offset ?? 0);
    const perGame = Number(process.env.MODSYNC_MODIO_MAX_PER_GAME ?? 5000);
    let produced = 0;
    const groups = new Map<number, Set<string>>();
    while (gi < MODIO_GAMES.length) {
      const g = MODIO_GAMES[gi];
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { gi, offset }, done: false };
      let groupValues = groups.get(g.id);
      if (g.categoryGroup && !groupValues) {
        try {
          const tg = await ctx.http.json<{ data: { name: string; tags: string[] }[] }>(`${API}/games/${g.id}/tags?api_key=${key}`);
          groupValues = new Set(tg.data.find((x) => x.name === g.categoryGroup)?.tags ?? []);
          groups.set(g.id, groupValues);
        } catch {}
      }
      const sort = ctx.mode === "recent" ? "-date_updated" : "-popular";
      const q = `api_key=${key}&_limit=${PAGE}&_offset=${offset}&_sort=${sort}${g.tagFilter ? `&tags=${encodeURIComponent(g.tagFilter)}` : ""}`;
      const res = await ctx.http.json<{ data: MioMod[]; result_total: number }>(`${API}/games/${g.id}/mods?${q}`);
      const mods = res.data.map((m) => parseModioMod(m, g.family, groupValues));
      if (mods.length) { await ctx.emit(mods); produced += mods.length; }
      offset += PAGE;
      ctx.log(`mod_io ${g.family} offset=${offset}/${res.result_total}`);
      if (!res.data.length || offset >= Math.min(res.result_total, perGame) || (ctx.mode === "recent" && offset >= 300)) { gi++; offset = 0; }
    }
    return { cursor: null, done: true };
  },
};
