/**
 * Shared types for the per-game one-click mod installers (lib/mods/installers/*).
 *
 * Shape of an install, for every family that uses this engine:
 *
 *   detect   — look at the server (through a GuestFs) and find WHERE mods go
 *              and what game version / loader it actually runs. If the loader
 *              the mod needs isn't there, stop here with a plain reason.
 *   resolve  — ask the mod's own source for the right build for THIS server
 *              (loader + game version), and walk its required dependencies.
 *              Declared incompatibilities come back too.
 *   download — lib/mods/safe-fetch.ts (allowlisted https, size cap, checksum),
 *              from the NX Labs local mirror first when it holds the file.
 *   place    — pure: bytes → the exact files to write (archives unpacked by
 *              lib/mods/archive.ts with traversal/symlink protection).
 *   apply    — lib/mods/engine.ts: conflict check, backup, staged write,
 *              rollback on failure, per-server state file on the guest.
 *
 * None of this ever reports success for a change it did not make.
 */
import type { Fetcher, Hashes } from "./safe-fetch";
import type { GuestFs } from "./guest-fs";

/** What the catalogue (GameMod) knows about a mod. Never trusted for paths. */
export type CatalogFacts = {
  id: string;
  gameFamily: string;
  slug: string;
  name: string;
  source: string;
  sourceId: string | null;
  url: string | null;
  category: string;
  appliesToVariant: string | null;
  loaders: string[];
  gameVersions: string[];
  serverSide: string | null;
};

/** What the DB knows about the server (the guest is asked separately in detect). */
export type ServerFacts = {
  id: string;
  family: string;
  variant: string | null;
  /** VERSION pinned in the server's game config, when it's a real version. */
  pinnedVersion: string | null;
  config: Record<string, unknown> | null;
};

export type Layout = {
  /** Directory everything for this game lives under; ownership reference. */
  base: string;
  /** Named target directories (plugins, mods, datapacks, …). */
  dirs: Record<string, string>;
  /** The game version the server really runs, when it can be read. */
  gameVersion: string | null;
  /** Loader/flavour actually present (e.g. "oxide" vs "carbon"). */
  flavour?: string | null;
};

export type RemoteFile = {
  url: string;
  filename: string;
  size: number | null;
  hashes: Hashes;
  /** Lets the NX Labs mirror find its copy (lib/mods/mirror.ts). */
  mirrorKey?: { source: string; projectId: string | null; versionId: string | null };
  headers?: Record<string, string>;
};

export type ResolvedPackage = {
  /** Unique per server state, e.g. "modrinth:P7dR8mSH", "thunderstore:ValheimModding-Jotunn". */
  key: string;
  name: string;
  version: string;
  versionId?: string | null;
  file: RemoteFile;
  /** Installer-defined placement strategy ("plugin-jar", "mod-jar", "datapack", "bepinex", …). */
  placement: string;
  /** Keys this package needs. */
  requires: string[];
  /** Keys that must NOT be installed alongside this one (declared upstream). */
  incompatible: { key: string; name: string }[];
  /** Bytes already fetched during resolve (e.g. a uMod .cs read for its // Requires: header). */
  prefetched?: Buffer;
  /** True for the mod the customer asked for; false for pulled-in dependencies. */
  root: boolean;
};

export type Resolution = {
  /** Dependency-first order; the last element is the root. */
  packages: ResolvedPackage[];
  notes: string[];
};

export type PlacedFile = {
  /** Absolute guest path (built with joinUnder — never from raw upstream strings). */
  path: string;
  data: Buffer;
  /** "replace": a file we may overwrite (backed up first), e.g. modpack config overrides. */
  overwrite?: "refuse" | "backup";
};

export type Compat =
  | { verdict: "ok"; detail: string }
  | { verdict: "mismatch"; detail: string }
  | { verdict: "unknown"; detail: string; reason?: "no-list" | "server-unpinned" }
  | { verdict: "unsupported"; detail: string };

export type InstallerCtx = {
  server: ServerFacts;
  layout: Layout;
  fetcher: Fetcher;
};

export interface FamilyInstaller {
  family: string;
  /** GameMod.source values this installer handles. */
  sources: readonly string[];
  /** One plain sentence: the real mechanism ("Paper plugin jar into plugins/"). */
  mechanism: string;
  /** Changes only take effect after a restart (TShock, BepInEx…) vs hot-load (Oxide). */
  restartRequired: boolean;
  /** Catalogue-only compatibility for THIS server (no network) — drives the badge. */
  compat(mod: CatalogFacts, server: ServerFacts): Compat;
  detect(fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout | { error: string }>;
  resolve(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }>;
  place(pkg: ResolvedPackage, bytes: Buffer, ctx: InstallerCtx): Promise<PlacedFile[] | { error: string }>;
  /** Files an older Nxeon installer placed for this mod before the engine existed. */
  legacyPaths?(mod: CatalogFacts, layout: Layout): string[];
  /** Post-change config sync (e.g. Factorio mod-list.json). Return files to write. */
  configure?(fs: GuestFs, layout: Layout, enabled: { key: string; name: string; version: string }[], all: { key: string; name: string }[]): Promise<PlacedFile[]>;
  /** Native enable/disable (config flag) instead of moving files aside. */
  nativeToggle?: boolean;
  /** Resolve needs the server's real game version (read on the guest when not pinned). */
  versionSensitive?: boolean;
}

export type OpOk = {
  ok: true;
  version?: string;
  restartRequired: boolean;
  /** Human list of what changed ("installed LuckPerms 5.5.71", "added dependency Fabric API"). */
  changed: string[];
  notes: string[];
};
export type OpResult = OpOk | { ok: false; error: string };
/**
 * Rust — uMod (Oxide) / Carbon C# plugins.
 *
 * Server: didstopia/rust-server, `-v /opt/rust:/steamcmd/rust`. Oxide keeps
 * plugins in `<server>/oxide/plugins`, Carbon in `<server>/carbon/plugins`;
 * both compile and HOT-LOAD a `.cs` dropped there (and unload it when it's
 * removed), so no restart is needed — which is why this installer says so.
 *
 * The framework must already be on the server: we look for the folder rather
 * than trusting the server-type label. A vanilla server is told plainly that
 * plugins need Oxide or Carbon.
 *
 * Source: umod.org's public JSON (`/plugins/<slug>.json` → `download_url`).
 * Dependencies are what uMod plugins actually declare: a `// Requires: Name`
 * comment at the top of the .cs, which Oxide itself enforces at load time.
 * We read it from the downloaded source and install those plugins too.
 * uMod publishes no checksum; downloads are size-capped and must look like C#.
 */
import { fetchJson } from "../safe-fetch";
import { joinUnder, safeFileName } from "../paths";
import type { FamilyInstaller, ResolvedPackage, ServerFacts, CatalogFacts, Compat } from "../types";

type UmodPlugin = { name: string; title: string; slug: string; download_url: string; latest_release_version?: string; latest_release_version_formatted?: string; games_detail?: { slug: string }[] };

/** `// Requires: Economics, ImageLibrary` → ["Economics","ImageLibrary"]. Only the file header. */
export function parseRequires(cs: string): string[] {
  const head = cs.split(/\r?\n/).slice(0, 60);
  const out: string[] = [];
  for (const line of head) {
    const m = /^\s*\/\/\s*Requires\s*:\s*(.+)$/i.exec(line);
    if (!m) continue;
    for (const n of m[1].split(/[,\s]+/)) if (/^[A-Za-z][A-Za-z0-9_]{1,63}$/.test(n)) out.push(n);
  }
  return [...new Set(out)];
}

export function looksLikeCSharpPlugin(text: string): boolean {
  return /namespace\s+(Oxide|Carbon)\.Plugins/.test(text) && /\[Info\s*\(/.test(text);
}

/** uMod slugs are the kebab-case of the class name ("ImageLibrary" → "image-library"). */
export function umodSlugFor(className: string): string {
  return className.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z])([A-Z][a-z])/g, "$1-$2").toLowerCase();
}

