/**
 * Factorio — the official mod portal (mods.factorio.com).
 *
 * Server: factoriotools/factorio, `-v /opt/factorio:/factorio`. Mods are the
 * portal's own zips placed as-is in /opt/factorio/mods, and switched on in
 * mods/mod-list.json — Factorio's own enable/disable file, which is also how
 * "disable" works here (the zip stays; `enabled: false`), exactly like the
 * in-game mod manager.
 *
 * DOWNLOADS NEED A FACTORIO ACCOUNT. The portal only serves files to a
 * factorio.com username + token (that is Wube's rule, not ours). The server
 * already has a place for them — `username` / `token` in
 * config/server-settings.json, the same fields the game uses for public
 * listing — so that's where we read them from, on the server, at install time.
 * They are never stored, logged or shown. Without them the install stops with
 * a plain explanation of where to add them.
 *
 * Releases are picked by the server's real Factorio version (read from its
 * log) and the portal's per-release `factorio_version`; dependencies follow
 * Factorio's own syntax (`!` incompatible, `?`/`(?)` optional, `~` required),
 * with version constraints honoured. Every download is checked against the
 * portal's published sha1.
 */
import { readZip, ArchiveError } from "../archive";
import { fetchJson } from "../safe-fetch";
import { joinUnder, safeFileName } from "../paths";
import type { CatalogFacts, Compat, FamilyInstaller, Layout, PlacedFile, ResolvedPackage } from "../types";

const ROOT = "/opt/factorio";
const MODS = `${ROOT}/mods`;
const PORTAL = "https://mods.factorio.com";
/** Shipped with the game (base + the official expansion's content mods). */
const BUILTIN = new Set(["base", "core", "space-age", "quality", "elevated-rails"]);

type FRelease = { download_url: string; file_name: string; info_json: { factorio_version: string; dependencies?: string[] }; released_at: string; version: string; sha1: string };
type FMod = { name: string; title: string; releases: FRelease[] };

export type FDep = { kind: "required" | "optional" | "incompatible"; name: string; op: string | null; version: string | null };

export function parseFactorioDep(s: string): FDep | null {
  const m = /^\s*(\(\?\)|\?|!|~)?\s*([A-Za-z0-9_\- ]+?)\s*(?:(<=|>=|=|<|>)\s*(\d+(?:\.\d+){0,2}))?\s*$/.exec(s);
  if (!m) return null;
  const pre = m[1] ?? "";
  const kind = pre === "!" ? "incompatible" : pre === "?" || pre === "(?)" ? "optional" : "required";
  return { kind, name: m[2].trim(), op: m[3] ?? null, version: m[4] ?? null };
}

function cmpVer(a: string, b: string): number {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (d) return d;
  }
  return 0;
}

export function satisfies(version: string, op: string | null, want: string | null): boolean {
  if (!op || !want) return true;
  const c = cmpVer(version, want);
  return op === ">=" ? c >= 0 : op === ">" ? c > 0 : op === "<=" ? c <= 0 : op === "<" ? c < 0 : c === 0;
}

/** Newest release for this Factorio major.minor that meets the constraint. */
export function pickFactorioRelease(releases: FRelease[], gameVersion: string, op: string | null, want: string | null): FRelease | null {
  const mm = gameVersion.split(".").slice(0, 2).join(".");
  return [...releases]
    .filter((r) => r.info_json?.factorio_version === mm && satisfies(r.version, op, want))
    .sort((a, b) => cmpVer(b.version, a.version))[0] ?? null;
}

export function factorioVersionFromLog(log: string): string | null {
  const m = /Factorio (\d+\.\d+\.\d+) \(build/.exec(log);
  return m ? m[1] : null;
}

async function credentials(layout: Layout, fs: Parameters<FamilyInstaller["detect"]>[0]): Promise<{ username: string; token: string } | null> {
  void layout;
  const raw = await fs.readFile(`${ROOT}/config/server-settings.json`, 1024 * 1024);
  if (!raw) return null;
  try {
    const j = JSON.parse(raw.toString("utf8")) as { username?: string; token?: string };
    const u = (j.username ?? "").trim();
    const t = (j.token ?? "").trim();
    if (/^[A-Za-z0-9_.\-]{1,64}$/.test(u) && /^[A-Za-z0-9]{8,128}$/.test(t)) return { username: u, token: t };
  } catch { /* fall through */ }
  return null;
}

/** mod-list.json with our mods set to their state; everyone else's entries untouched. */
export function syncModList(existing: string | null, ours: { name: string; enabled: boolean }[], allOurs: string[]): string {
  let list: { name: string; enabled: boolean }[] = [];
  try {
    const j = existing ? (JSON.parse(existing) as { mods?: { name: string; enabled: boolean }[] }) : null;
    list = Array.isArray(j?.mods) ? j!.mods! : [];
  } catch {
    list = [];
  }
  if (!list.some((m) => m.name === "base")) list.unshift({ name: "base", enabled: true });
  const mine = new Set(allOurs);
  list = list.filter((m) => !mine.has(m.name) || ours.some((o) => o.name === m.name));
  for (const o of ours) {
    const i = list.findIndex((m) => m.name === o.name);
    if (i >= 0) list[i] = { ...list[i], enabled: o.enabled };
    else list.push({ name: o.name, enabled: o.enabled });
  }
  return JSON.stringify({ mods: list }, null, 2) + "\n";
}

const nameOfKey = (k: string) => k.replace(/^factorio:/, "");

export const factorioInstaller: FamilyInstaller = {
  family: "factorio",
  sources: ["factorio_portal"],
  mechanism: "Official mod-portal zips into /opt/factorio/mods + mod-list.json (needs the factorio.com username/token in server-settings.json).",
  restartRequired: true,
  nativeToggle: true,
  versionSensitive: true,

  compat(): Compat {

  compat(): Compat {
    return { verdict: "unknown", reason: "no-list", detail: "Checked against your server's Factorio version at install time." };
  },

  async detect(fs) {
    if ((await fs.stat(ROOT))?.type !== "dir") return { error: "Couldn't find this server's Factorio folder — is the server fully set up?" };
    const log = await fs.readFile(`${ROOT}/factorio-current.log`, 16 * 1024 * 1024);
    const gameVersion = log ? factorioVersionFromLog(log.toString("utf8")) : null;
    if (!gameVersion) return { error: "Couldn't read this server's Factorio version — start it once, then try again." };
