    const cred = await credentials(layout, fs);
    if (!cred) {
      return {
        error:
          "Factorio's mod portal only lets a factorio.com account download mods. Add your factorio.com username and token (factorio.com → Profile → token) to config/server-settings.json in Files, then try again.",
