    (layout as Layout & { _cred?: typeof cred })._cred = cred;
    return layout;
  },

  async resolve(mod: CatalogFacts, ctx) {
    const gv = ctx.layout.gameVersion;
    if (!gv) return { error: "Couldn't read this server's Factorio version." };
    const cred = (ctx.layout as Layout & { _cred?: { username: string; token: string } })._cred ?? null;
    const out: ResolvedPackage[] = [];
    const seen = new Set<string>();
    const notes: string[] = [];
    const visit = async (name: string, op: string | null, want: string | null, isRoot: boolean, depth: number): Promise<string | null> => {
      if (BUILTIN.has(name)) return null;
      if (seen.has(name)) return null;
      seen.add(name);
      if (seen.size > 40) return "This mod pulls in more than 40 dependencies — too many for one click.";
      let m: FMod;
      try {
        m = await fetchJson<FMod>(ctx.fetcher, `${PORTAL}/api/mods/${encodeURIComponent(name)}/full`);
