      const rel = pickFactorioRelease(m.releases ?? [], gv, op, want);
      if (!rel) return `${m.title} has no release for Factorio ${gv.split(".").slice(0, 2).join(".")}${op ? ` matching ${op} ${want}` : ""} — nothing was installed.`;
