// ─── paths ──────────────────────────────────────────────────────────────────

test("normalizeRel refuses traversal, absolute, drive letters, NUL and option-looking names", () => {
  for (const bad of ["../x", "a/../../etc/passwd", "/etc/passwd", "C:/Windows/x.dll", "C:\\x", "a/\0b", "-rf", "a//b", "a/./b/..", "..", "a/b/ "]) {
    assert.equal(normalizeRel(bad), null, bad);
  }
  assert.deepEqual(normalizeRel("plugins\\Foo\\Foo.dll"), ["plugins", "Foo", "Foo.dll"]);
  assert.deepEqual(normalizeRel("./mods/sodium-fabric-0.6.0+mc1.21.1.jar"), ["mods", "sodium-fabric-0.6.0+mc1.21.1.jar"]);
  assert.deepEqual(normalizeRel("config/"), ["config"]);
});

test("joinUnder never leaves its base; isSafeAbs/safeFileName allowlist", () => {
  assert.equal(joinUnder("/opt/mc/plugins", ["LuckPerms.jar"]), "/opt/mc/plugins/LuckPerms.jar");
  assert.throws(() => joinUnder("/opt/mc/plugins", ["..", "x"]));
  assert.throws(() => joinUnder("/opt/mc/plugins", "../../root/.ssh/authorized_keys"));
  assert.equal(isSafeAbs("/"), false);
  assert.equal(isSafeAbs("/opt/mc/../etc"), false);
  assert.equal(safeFileName("https://cdn/x/LuckPerms-Bukkit-5.5.71.jar", [".jar"]), "LuckPerms-Bukkit-5.5.71.jar");
  assert.equal(safeFileName("evil.jar;rm -rf /", [".jar"]), null);
  assert.equal(safeFileName("x.exe", [".jar"]), null);
});

// ─── archive safety ─────────────────────────────────────────────────────────

test("readZip round-trips stored + deflated entries and verifies CRC", () => {
  const z = makeZip([{ name: "a.txt", data: "hello" }, { name: "dir/", dir: true }, { name: "dir/b.bin", data: Buffer.alloc(4096, 7), deflate: false }]);
  const e = readZip(z);
  assert.equal(e.find((x) => x.path.join("/") === "a.txt")!.data.toString(), "hello");
  assert.equal(e.find((x) => x.path.join("/") === "dir/b.bin")!.data.length, 4096);
  assert.throws(() => readZip(makeZip([{ name: "a.txt", data: "hello", badCrc: true }])), ArchiveError);
});

test("readZip rejects zip-slip, absolute paths, symlinks, encrypted entries and duplicates", () => {
