cd /tank/nxeon-wt-mods-audit && cat > lib/mods/installers/corekeeper.ts <<'EOF'
/**
 * Core Keeper — mods from mod.io, placed in the dedicated server's own Mods folder.
 *
 * Server: escaping/core-keeper-dedicated (prisma/seed-wave3-games.ts),
 * `-v /opt/corekeeper/files:/home/steam/core-keeper-dedicated`. Per the game's
 * modding wiki a dedicated server has no mod.io integration of its own: each
 * mod is unzipped into its own folder under
 * `<server>/CoreKeeperServer_Data/StreamingAssets/Mods/` (folder name only has
 * to be unique) and the server syncs them to joining players on start.
 * Dependencies are NOT resolved by the game, so we install the mod's declared
 * mod.io dependencies ourselves.
 *
 * DOWNLOADS use the read-only mod.io API key from the worker's environment
 * (MODIO_API_KEY, never stored, logged or shown — FetchError messages carry no
 * URL). `GET /games/{g}/mods/{m}` gives the live modfile with a short-lived
 * `download.binary_url` and an MD5; we download inside `resolve` (the URL
 * expires) and verify the MD5 before anything is placed. A game that requires
 * authenticated (OAuth) downloads answers 401/403 and the install stops with a
 * plain message — it never half-installs.
 *
 * NOT verified against a live Core Keeper server (no test VM in the audit task):
 * built from the official docs + mod.io's REST reference; see docs/MOD-INSTALL-COVERAGE.md.
 */
import { createHash } from "node:crypto";
import { readZip, ArchiveError } from "../archive";
import { fetchJson } from "../safe-fetch";
import { joinUnder, isSafeSegment } from "../paths";
import type { CatalogFacts, Compat, FamilyInstaller, InstallerCtx, PlacedFile, ResolvedPackage } from "../types";

const API = "https://api.mod.io/v1";
export const COREKEEPER_GAME_ID = 5289;
const SERVER_ROOT = "/opt/corekeeper/files";
const STREAMING = `${SERVER_ROOT}/CoreKeeperServer_Data/StreamingAssets`;
const MODS = `${STREAMING}/Mods`;

type MioFile = { id: number; filename?: string; version?: string | null; filesize?: number; filehash?: { md5?: string }; download?: { binary_url?: string; date_expires?: number } };
type MioMod = { id: number; name: string; name_id: string; tags?: { name: string }[]; modfile?: MioFile | null };
type MioDep = MioMod & { dependency_depth?: number };

export function modioKey(): string | null {
  if (process.env.NXEON_MODIO_INSTALL === "off") return null;
  const k = (process.env.MODIO_API_KEY ?? "").trim();
  return /^[A-Za-z0-9]{16,64}$/.test(k) ? k : null;
}

/** Folder name for a mod: stable, unique per mod.io id, shell-inert. */
export function modFolder(m: { id: number; name_id?: string }): string {
  const base = (m.name_id ?? "mod").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "mod";
  return `${base}-${m.id}`;
}

/** Client-only tag → the server must not load it (can stop the server starting). */
export function isClientOnly(tags: { name: string }[] | undefined): boolean {
  const t = (tags ?? []).map((x) => x.name.toLowerCase());
  return t.includes("client") && !t.includes("server");
}

/**
 * Zip → files under `<modsDir>/<folder>/`. The mod's ModManifest.json may sit
 * at the zip root or inside ONE wrapper folder (stripped). Pure; fixture-tested.
 */
export function coreKeeperPlacement(entries: { path: string[]; dir: boolean; data: Buffer }[], modsDir: string, folder: string): PlacedFile[] | { error: string } {
  if (!isSafeSegment(folder)) return { error: "unsafe mod folder name" };
  const files = entries.filter((e) => !e.dir);
  const isManifest = (s: string) => s.toLowerCase() === "modmanifest.json";
  let strip = 0;
  if (files.some((e) => e.path.length === 1 && isManifest(e.path[0]))) strip = 0;
  else {
    const tops = new Set(files.map((e) => e.path[0]));
    if (tops.size === 1 && files.some((e) => e.path.length === 2 && isManifest(e.path[1]))) strip = 1;
    else return { error: "this download has no ModManifest.json, so it isn't a Core Keeper mod we can place" };
  }
  const out: PlacedFile[] = [];
  for (const e of files) {
    const rel = e.path.slice(strip);
    if (rel.length === 0) continue;
    out.push({ path: joinUnder(modsDir, [folder, ...rel]), data: e.data });
  }
  return out.length ? out : { error: "the download was empty" };
}

export const corekeeperInstaller: FamilyInstaller = {
  family: "corekeeper",
  sources: ["mod_io"],
  mechanism: "mod.io mod zips (+ declared dependencies) unzipped into CoreKeeperServer_Data/StreamingAssets/Mods/<mod>/ — the server syncs them to players on start.",
  restartRequired: true,

  compat(mod: CatalogFacts): Compat {
    if (mod.serverSide === "unsupported") return { verdict: "unsupported", detail: "This is a client-side mod — it runs in each player's own game and would stop a server from starting. Players install it themselves." };
    return { verdict: "unknown", reason: "no-list", detail: "Players joining need the same mod installed in their own game." };
  },

  async detect(fs) {
    if ((await fs.stat(SERVER_ROOT))?.type !== "dir") return { error: "Couldn't find this server's Core Keeper folder — is the server fully set up?" };
    if ((await fs.stat(STREAMING))?.type !== "dir") return { error: "This server hasn't finished its first start yet (its game files aren't there). Start it once, then try again." };
    if (!modioKey()) return { error: "One-click install for Core Keeper mods isn't available right now. Download the mod from its page and upload it in Files." };
    await fs.mkdirp(MODS);
    return { base: SERVER_ROOT, dirs: { mods: MODS }, gameVersion: null };
  },

  async resolve(mod, ctx: InstallerCtx) {
    const key = modioKey();
    if (!key) return { error: "One-click install for Core Keeper mods isn't available right now." };
    const id = Number((mod.sourceId ?? "").trim());
    if (!Number.isInteger(id) || id <= 0) return { error: "This catalogue entry has no valid mod id." };
    const q = `api_key=${encodeURIComponent(key)}`;
    const notes: string[] = ["Players who join need the same mod installed in their own game."];
    const order: ResolvedPackage[] = [];

    const pack = async (m: MioMod, isRoot: boolean, requires: string[]): Promise<string | null> => {
      const f = m.modfile;
      const url = f?.download?.binary_url;
      if (!f || !url || !/^[0-9a-f]{32}$/i.test(f.filehash?.md5 ?? "")) return `${isRoot ? mod.name : m.name} has no downloadable file right now.`;
      if (isClientOnly(m.tags)) return isRoot ? `${m.name} is a client-side mod — players install it themselves, it doesn't go on the server.` : `${mod.name} needs ${m.name}, which is client-side only.`;
      let bytes: Buffer;
      try {
        // The signed URL expires, so fetch now (inside resolve) and verify before anything is placed.
        const r = await ctx.fetcher(url, { maxBytes: 200 * 1024 * 1024, timeoutMs: 180_000, headers: {} });
        bytes = r.bytes;
      } catch (e) {
        const msg = e instanceof Error ? e.message : "";
        if (/HTTP 40[13]/.test(msg)) return `${m.name} can only be downloaded by a signed-in player, so we can't fetch it for you — download it from its page and upload it in Files.`;
        throw e;
      }
      if (createHash("md5").update(bytes).digest("hex") !== f.filehash!.md5!.toLowerCase()) return `The download for ${m.name} didn't match its published checksum — nothing was installed.`;
      const folder = modFolder(m);
      order.push({
        key: `mod_io:${m.id}`,
        name: isRoot ? mod.name : m.name,
        version: (f.version || f.filename || String(f.id)).slice(0, 80),
        versionId: String(f.id),
        file: { url: `${API}/games/${COREKEEPER_GAME_ID}/mods/${m.id}/files/${f.id}`, filename: `${folder}.zip`, size: bytes.length, hashes: {} },
        placement: folder,
        requires,
        incompatible: [],
        prefetched: bytes,
        root: isRoot,
      });
      return null;
    };

    let root: MioMod;
    let deps: MioDep[] = [];
    try {
      root = await fetchJson<MioMod>(ctx.fetcher, `${API}/games/${COREKEEPER_GAME_ID}/mods/${id}?${q}`);
      const d = await fetchJson<{ data?: MioDep[] }>(ctx.fetcher, `${API}/games/${COREKEEPER_GAME_ID}/mods/${id}/dependencies?recursive=true&${q}`);
      deps = d.data ?? [];
    } catch (e) {
      const msg = e instanceof Error ? e.message : "";
      if (/HTTP 404/.test(msg)) return { error: `Couldn't find ${mod.name} — it may have been removed by its author.` };
      return { error: "Couldn't reach the mod site just now — try again in a minute." };
    }
    if (deps.length > 20) return { error: "This mod pulls in more than 20 dependencies — too many for one click." };
    // Deepest dependencies first, root last (engine installs in this order).
    const sorted = [...deps].sort((a, b) => (b.dependency_depth ?? 0) - (a.dependency_depth ?? 0));
    const depKeys = sorted.map((d) => `mod_io:${d.id}`);
    for (const d of sorted) {
      const e = await pack(d, false, []);
      if (e) return { error: e };
    }
    const e = await pack(root, true, depKeys);
    if (e) return { error: e };
    return { packages: order, notes };
  },

  async place(pkg, bytes, ctx) {
    try {
      const entries = readZip(bytes);
      return coreKeeperPlacement(entries, ctx.layout.dirs.mods, pkg.placement);
    } catch (e) {
      return { error: `${pkg.name} isn't a valid mod zip (${e instanceof ArchiveError ? e.message : "unreadable"}).` };
    }
  },
};
