type ModRow = GameMod;

function compatFor(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>): Compat {
  const inst = engineInstallerFor(family, m.source) ?? ENGINE_INSTALLERS[family];
  if (inst) return inst.compat(catalogFacts(m), facts);
  const c = modCompat({ gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide }, { gameVersion: facts.pinnedVersion, variant: facts.variant });
  return c.verdict === "unknown" ? { verdict: "unknown", detail: c.detail, reason: c.reason } : (c as Compat);
}

function toPanel(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>, st?: { status: string; version: string | null; error: string | null } | null): PanelMod {
  const sup = installSupport(family, m.source);
  const cov = familyCoverage(family);
  const compat = compatFor(family, m, facts);
  return {
    id: m.id,
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    url: m.url,
    description: m.description,
    iconUrl: m.iconUrl,
    authorName: m.authorName,
    downloads: m.downloads,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    impact: m.impact,
    impactNote: m.impactNote,
    paid: m.paid,
    featured: m.featured,
    gameVersions: m.gameVersions.slice(-8),
    loaders: m.loaders.slice(0, 6),
    latestUpdated: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    compat,
    manualInstall: cov.mode === "unavailable" ? cov.reason : !sup.ok ? sup.message : compat.verdict === "unsupported" ? compat.detail : null,
    status: st?.status ?? null,
    version: st?.version ?? null,
    error: st?.error ?? null,
  };
}

