test("engine: install with dependency → idempotent re-run → disable/enable → update → uninstall", async () => {
  const g = fakeGuest();
  try {
    const jars = { "myplugin-1.0.0.jar": jar("MyPlugin"), "myplugin-1.1.0.jar": jar("MyPluginV2"), "corelib-2.0.jar": jar("CoreLib") };
    const server = mcServer("paper");
    const mod = mcMod({ id: "gm_my", slug: "myplugin", name: "My Plugin", sourceId: "myplugin" });

    let up = fakeModrinth(jars);
    const r1 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(r1.ok, JSON.stringify(r1));
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(existsSync(g.at("opt/mc/plugins/corelib-2.0.jar")));
    assert.equal(r1.ok && r1.restartRequired, true);
    assert.deepEqual(r1.ok && r1.changed, ["added dependency Core Lib 2.0", "installed My Plugin 1.0.0"]);
    const st = await loadState(g.fs, "minecraft");
    assert.deepEqual(Object.keys(st.packages).sort(), ["modrinth:LIB", "modrinth:P1"]);
    assert.deepEqual(st.packages["modrinth:LIB"].roots, ["gm_my"]);

    // idempotent: second run downloads nothing and changes nothing
    up = fakeModrinth(jars);
    const r2 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(r2.ok && r2.changed.length === 0 && r2.restartRequired === false, JSON.stringify(r2));
    assert.ok(!up.calls.some((c) => c.includes("cdn.modrinth.com")), "no jar re-download");

    // disable moves it aside; enable puts it back
    const d = await setDisabled(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, true);
    assert.ok(d.ok, JSON.stringify(d));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(existsSync(g.at("opt/mc/plugins/corelib-2.0.jar")), "dependency stays");
    const again = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(!again.ok && /disabled/.test(again.error));
    const e = await setDisabled(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, false);
    assert.ok(e.ok);
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));

    // update: new version replaces the old file, backup kept
    up = fakeModrinth(jars, { pluginVersion: "1.1.0" });
    const u = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, "update");
    assert.ok(u.ok, JSON.stringify(u));
    assert.deepEqual(u.ok && u.changed, ["updated My Plugin 1.0.0 → 1.1.0"]);
