import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";

import { LocalGuestFs } from "../lib/mods/guest-fs.ts";
import { installOrUpdate, uninstall } from "../lib/mods/engine.ts";
import { hashAll, validateUrl, FetchError, type Fetcher } from "../lib/mods/safe-fetch.ts";
import { corekeeperInstaller, coreKeeperPlacement, isClientOnly, modFolder } from "../lib/mods/installers/corekeeper.ts";
import { familyCoverage, customerCoverageText, COVERAGE_UNAVAILABLE } from "../lib/mods/installers/index.ts";
import { installSupport } from "../lib/mod-install-support.ts";
import { manualGuide, modConfigFolder } from "../lib/mods/manual-install.ts";
import { makeZip } from "./_mods-zip-fixture.ts";
import type { CatalogFacts, ServerFacts } from "../lib/mods/types.ts";

const KEY = "0123456789abcdef0123456789abcdef";
const md5 = (b: Buffer) => createHash("md5").update(b).digest("hex");

const server: ServerFacts = { id: "s1", family: "corekeeper", variant: "default", pinnedVersion: null, config: null };
const mod = (id: number, name: string): CatalogFacts => ({ id: `gm_${id}`, gameFamily: "corekeeper", slug: name.toLowerCase().replace(/ /g, "-"), name, source: "mod_io", sourceId: String(id), url: `https://mod.io/g/corekeeper/m/x${id}`, category: "Mods", appliesToVariant: null, loaders: [], gameVersions: [], serverSide: null });

function fakeModio(zips: Record<number, Buffer>, opts: { clientOnlyDep?: boolean; forbid?: boolean; badMd5?: boolean } = {}) {
  const meta = (id: number, name_id: string, tags: string[] = []) => ({
    id, name: name_id, name_id, tags: tags.map((name) => ({ name })),
    modfile: { id: id * 10, filename: `${name_id}.zip`, version: "1.0", filesize: zips[id].length, filehash: { md5: opts.badMd5 ? "0".repeat(32) : md5(zips[id]) }, download: { binary_url: `https://g-5289.modcdn.io/m/${id}/${name_id}.zip` } },
  });
  const calls: string[] = [];
  const fetcher: Fetcher = async (url, o) => {
    calls.push(url);
    validateUrl(url, o.allow);
    const u = new URL(url);
    let body: Buffer | null = null;
    let m: RegExpExecArray | null;
    if ((m = /^\/v1\/games\/5289\/mods\/(\d+)\/dependencies$/.exec(u.pathname))) {
      assert.equal(u.searchParams.get("api_key"), KEY);
      body = Buffer.from(JSON.stringify({ data: m[1] === "1" ? [{ ...meta(2, "corelib", opts.clientOnlyDep ? ["Client"] : ["Server"]), dependency_depth: 0 }] : [] }));
    } else if ((m = /^\/v1\/games\/5289\/mods\/(\d+)$/.exec(u.pathname))) body = zips[Number(m[1])] ? Buffer.from(JSON.stringify(meta(Number(m[1]), m[1] === "1" ? "enemy-bars" : "corelib", ["Server"]))) : null;
    else if (u.hostname.endsWith(".modcdn.io")) {
      if (opts.forbid) throw new FetchError("upstream answered HTTP 403", "status");
      body = zips[Number(u.pathname.split("/")[2])] ?? null;
    }
    if (!body) throw new FetchError("upstream answered HTTP 404", "status");
    return { bytes: body, finalUrl: url, status: 200, ...hashAll(body) };
  };
  return { fetcher, calls };
}

const modZip = (n: string) => makeZip([{ name: "ModManifest.json", data: `{"name":"${n}"}` }, { name: "Assets/x.bundle", data: Buffer.from([1, 2, 3]) }]);
const MODS = "opt/corekeeper/files/CoreKeeperServer_Data/StreamingAssets/Mods";

function guest(withGame = true) {
  const root = mkdtempSync(path.join(tmpdir(), "nxeon-ck-"));
  if (withGame) mkdirSync(path.join(root, "opt/corekeeper/files/CoreKeeperServer_Data/StreamingAssets"), { recursive: true });
  return { root, fs: new LocalGuestFs(root), at: (p: string) => path.join(root, p) };
}

test("core keeper: install with dependency places each mod in its own folder, then uninstalls cleanly", async () => {
  process.env.MODIO_API_KEY = KEY;
  const g = guest();
  try {
    const up = fakeModio({ 1: modZip("EnemyBars"), 2: modZip("CoreLib") });
    const r = await installOrUpdate(corekeeperInstaller, mod(1, "Enemy Health Bars"), server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(r.ok, JSON.stringify(r));
    assert.ok(existsSync(g.at(`${MODS}/enemy-bars-1/ModManifest.json`)));
    assert.ok(existsSync(g.at(`${MODS}/corelib-2/Assets/x.bundle`)));
    assert.equal(r.ok && r.restartRequired, true);
    // the key never lands on the guest
    assert.ok(!readFileSync(g.at("root/.nxeon-mods/state.json"), "utf8").includes(KEY));
    const u = await uninstall(corekeeperInstaller, mod(1, "Enemy Health Bars"), server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(u.ok, JSON.stringify(u));
    assert.ok(!existsSync(g.at(`${MODS}/enemy-bars-1`)) && !existsSync(g.at(`${MODS}/corelib-2`)));
  } finally { rmSync(g.root, { recursive: true, force: true }); }
});

test("core keeper: refusals are plain and nothing is written", async () => {
  process.env.MODIO_API_KEY = KEY;
  const cases: [string, Parameters<typeof fakeModio>[1], RegExp, boolean?][] = [
    ["client-only dependency", { clientOnlyDep: true }, /client-side/],
    ["signed-in-only download", { forbid: true }, /signed-in player/],
    ["checksum mismatch", { badMd5: true }, /checksum/],
  ];
  for (const [label, opts, re] of cases) {
    const g = guest();
    try {
      const r = await installOrUpdate(corekeeperInstaller, mod(1, "Enemy Health Bars"), server, { fs: g.fs, fetcher: fakeModio({ 1: modZip("A"), 2: modZip("B") }, opts).fetcher });
      assert.ok(!r.ok && re.test(r.error), `${label}: ${JSON.stringify(r)}`);
      assert.ok(!existsSync(g.at(MODS)) || !existsSync(g.at(`${MODS}/enemy-bars-1`)), label);
    } finally { rmSync(g.root, { recursive: true, force: true }); }
  }
  // game not set up yet / key missing
  const g = guest(false);
  try {
    const r = await installOrUpdate(corekeeperInstaller, mod(1, "X"), server, { fs: g.fs, fetcher: fakeModio({ 1: modZip("A"), 2: modZip("B") }).fetcher });
    assert.ok(!r.ok && /Core Keeper folder/.test(r.error));
  } finally { rmSync(g.root, { recursive: true, force: true }); }
});

test("core keeper: without the platform key the family reads as unavailable, with customer-safe wording", () => {
  const prev = process.env.MODIO_API_KEY;
  delete process.env.MODIO_API_KEY;
  try {
    const c = familyCoverage("corekeeper");
    assert.equal(c.mode, "unavailable");
    process.env.MODIO_API_KEY = KEY;
    assert.equal(familyCoverage("corekeeper").mode, "engine");
    process.env.NXEON_MODIO_INSTALL = "off";
    assert.equal(familyCoverage("corekeeper").mode, "unavailable");
  } finally {
    delete process.env.NXEON_MODIO_INSTALL;
    if (prev) process.env.MODIO_API_KEY = prev; else delete process.env.MODIO_API_KEY;
  }
  // only Core Keeper's mod.io rows are installable; other mod.io games stay manual
  assert.ok(installSupport("corekeeper", "mod_io").ok);
  for (const f of ["eco", "mordhau", "sandstorm", "spaceengineers"]) assert.equal(installSupport(f, "mod_io").ok, false, f);
});

test("placement: manifest at root or one wrapper folder; no manifest is refused", () => {
  const e = (p: string) => ({ path: p.split("/"), dir: false, data: Buffer.from("x") });
  const a = coreKeeperPlacement([e("ModManifest.json"), e("a/b.dll")], "/m", "x-1");
  assert.ok(Array.isArray(a) && a.map((f) => f.path).join() === "/m/x-1/ModManifest.json,/m/x-1/a/b.dll");
  const b = coreKeeperPlacement([e("Wrap/ModManifest.json"), e("Wrap/a.dll")], "/m", "x-1");
  assert.ok(Array.isArray(b) && b[1].path === "/m/x-1/a.dll");
  assert.ok("error" in (coreKeeperPlacement([e("a.dll")], "/m", "x-1") as object));
  assert.ok(isClientOnly([{ name: "Client" }]) && !isClientOnly([{ name: "Client" }, { name: "Server" }]));
  assert.equal(modFolder({ id: 7, name_id: "My Mod!!" }), "my-mod-7");
});

test("customer wording: no internal terms anywhere in the family copy", () => {
  const bad = /api key|not wired|wired|provider|MODIO|STEAM_WEB|ENABLE_|env var|\.env|auth key/i;
  for (const [fam, reason] of Object.entries(COVERAGE_UNAVAILABLE)) assert.ok(!bad.test(reason), `${fam}: ${reason}`);
  for (const fam of ["minecraft", "ark", "tf2", "terraria", "satisfactory", "palworld"]) assert.ok(!bad.test(customerCoverageText(fam)), fam);
  assert.ok(manualGuide("corekeeper", "mod.io").steps.join(" ").includes("StreamingAssets/Mods"));
  assert.equal(modConfigFolder("rust", "oxide"), "/opt/rust/oxide/config");
  assert.equal(modConfigFolder("rust", "vanilla"), null);
  assert.equal(modConfigFolder("valheim", "bepinex"), null);
});
